import React, { useMemo, useState } from 'react';
import {
  BellRing,
  Brain,
  Brush,
  Ellipsis,
  FileText,
  Heart,
  Image,
  Landmark,
  List,
  MessageCircle,
  Repeat2,
  UsersRound
} from 'lucide-react';
import styles from './Posts.module.scss';
import { FEED_WEIGHTS } from '../../recommendation/feedConfig';

const POSTS = [
  {
    id: 1,
    author: 'Charles Deo',
    handle: '@Charles_deo',
    time: '15mins ago',
    category: 'History',
    title: 'New Blazer out here... $500!!!!!',
    text: 'Lorem Ipsum is simply dummy text of the printing and typesetting industry. Lorem Ipsum has been the industry standard text ever since the 1500s, when an unknown printer took a galley of type and scrambled it to make a type specimen book.',
    likes: 1498,
    shares: 1498,
    comments: 50,
    isFriend: true,
    isNew: true
  },
  {
    id: 2,
    author: 'Maria Gonzalez',
    handle: '@maria.gonzalez',
    time: '28mins ago',
    category: 'Philosophy',
    title: 'Защо идеите имат история',
    text: 'Когато промениш контекста, променяш и значението на тезите. Историята на идеите не е архив, а жива среда за дебат, в която понятията сменят функцията си.',
    likes: 938,
    shares: 332,
    comments: 42,
    isFriend: true,
    isNew: false
  },
  {
    id: 3,
    author: 'Liam O\'Brien',
    handle: '@liam.obrien',
    time: '43mins ago',
    category: 'Art',
    title: 'Кино езикът на авангарда',
    text: 'Визуалният ритъм и монтажът променят не само формата, но и начина, по който мислим сюжета. Авангардът работи със зрителското внимание като материал.',
    likes: 410,
    shares: 121,
    comments: 18,
    isFriend: false,
    isNew: true
  },
  {
    id: 4,
    author: 'Sofia Rossi',
    handle: '@sofia.rossi',
    time: '1h ago',
    category: 'Debates',
    title: 'Етика в публичния разговор',
    text: 'Няма плурализъм без общи правила за аргумент. Свободата на мнение работи добре тогава, когато се комбинира с отговорност към фактите.',
    likes: 216,
    shares: 77,
    comments: 30,
    isFriend: false,
    isNew: false
  }
];

const FRIENDS = [
  { name: 'Eddie Lobanovskiy', email: 'lobanovskiy@gmail.com' },
  { name: 'Alexey Stave', email: 'alexeyts@gmail.com' },
  { name: 'Anton Tkacheve', email: 'tkacheveanton@gmail.com' },
  { name: 'Maria Gonzalez', email: 'maria.gonzalez@email.com' },
  { name: 'Jin Park', email: 'jin.park@email.com' },
  { name: 'Liam O\'Brien', email: 'liam.obrien@email.com' },
  { name: 'Aisha Khan', email: 'aisha.khan@email.com' },
  { name: 'Ravi Patel', email: 'ravi.patel@email.com' },
  { name: 'Sofia Rossi', email: 'sofia.rossi@email.com' },
  { name: 'David Kim', email: 'david.kim@email.com' }
];

const LEFT_CATEGORIES = [
  { name: 'History', icon: Landmark },
  { name: 'Philosophy', icon: Brain },
  { name: 'Art', icon: Brush },
  { name: 'Debates', icon: MessageCircle },
  { name: 'Communities', icon: UsersRound },
  { name: 'Messages', icon: BellRing }
];

const takeUnique = (source, count, selectedIds) => {
  const result = [];
  for (const item of source) {
    if (result.length >= count) break;
    if (selectedIds.has(item.id)) continue;
    selectedIds.add(item.id);
    result.push(item);
  }
  return result;
};

const shuffle = (arr) => [...arr].sort(() => Math.random() - 0.5);

export default function Posts({ onNavigate }) {
  const [searchText, setSearchText] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('All');

  const displayedPosts = useMemo(() => {
    const q = searchText.trim().toLowerCase();

    const base = POSTS.filter((post) => {
      const matchesQuery = q.length === 0 || post.title.toLowerCase().includes(q) || post.text.toLowerCase().includes(q) || post.author.toLowerCase().includes(q);
      const matchesCategory = selectedCategory === 'All' || post.category === selectedCategory;
      return matchesQuery && matchesCategory;
    });

    const interestPool = shuffle(base.filter((post) => selectedCategory === 'All' || post.category === selectedCategory || post.isFriend));
    const freshPool = shuffle(base.filter((post) => post.isNew));
    const randomPool = shuffle(base);

    const total = Math.min(base.length, 8);
    const interestCount = Math.round(total * (FEED_WEIGHTS.interest / 100));
    const freshCount = Math.round(total * (FEED_WEIGHTS.fresh / 100));
    const randomCount = Math.max(0, total - interestCount - freshCount);

    const selectedIds = new Set();
    const fromInterest = takeUnique(interestPool, interestCount, selectedIds);
    const fromFresh = takeUnique(freshPool, freshCount, selectedIds);
    const fromRandom = takeUnique(randomPool, randomCount, selectedIds);

    return [...fromInterest, ...fromFresh, ...fromRandom];
  }, [searchText, selectedCategory]);

  return (
    <div className={styles.page}>
      <main className={styles.shell}>
        <section className={styles.board}>
          <aside className={styles.leftPanel}>
            <div className={styles.categories}>
              <p>Categories</p>
              <button
                type="button"
                className={`${styles.categoryItem} ${selectedCategory === 'All' ? styles.selectedCategory : ''}`}
                onClick={() => setSelectedCategory('All')}
              >
                <span>All</span>
              </button>

              {LEFT_CATEGORIES.map(({ name, icon: Icon }) => (
                <button
                  key={name}
                  type="button"
                  className={`${styles.categoryItem} ${selectedCategory === name ? styles.selectedCategory : ''}`}
                  onClick={() => setSelectedCategory(name)}
                >
                  <span>{name}</span>
                  <Icon size={20} />
                </button>
              ))}
            </div>
          </aside>

          <section className={styles.feedColumn}>
            <article className={styles.createPostCard}>
              <div className={styles.avatar} aria-hidden="true">👨🏽</div>
              <div className={styles.createBody}>
                <input
                  type="text"
                  value={searchText}
                  onChange={(event) => setSearchText(event.target.value)}
                  placeholder="What's happening ?"
                />
                <div className={styles.createActions}>
                  <div className={styles.createIcons}>
                    <Image size={18} />
                    <List size={18} />
                    <MessageCircle size={18} />
                    <FileText size={18} />
                  </div>
                  <button type="button">Post</button>
                </div>
              </div>
            </article>

            {displayedPosts.map((post) => (
              <article key={post.id} className={styles.postCard}>
                <header className={styles.postHeader}>
                  <div className={styles.avatar} aria-hidden="true">👨🏽</div>
                  <div className={styles.postMeta}>
                    <div className={styles.authorRow}>
                      <strong>{post.author}</strong>
                      <UsersRound size={18} />
                    </div>
                    <span>{post.time}</span>
                  </div>
                  <button type="button" className={styles.moreBtn}>
                    <Ellipsis size={18} />
                  </button>
                </header>

                <p className={styles.postTitle}>{post.title}</p>
                <p className={styles.postText}>{post.text}</p>

                <footer className={styles.postFooter}>
                  <div>
                    <Heart size={19} /> {post.likes.toLocaleString()}
                  </div>
                  <div>
                    <Repeat2 size={19} /> {post.shares.toLocaleString()}
                  </div>
                  <div>
                    <MessageCircle size={19} /> {post.comments}
                  </div>
                </footer>

                <button type="button" className={styles.seeMore}>See more</button>
              </article>
            ))}
          </section>

          <aside className={styles.rightPanel}>
            <article className={styles.profileCard}>
              <div className={styles.avatar} aria-hidden="true">👨🏽</div>
              <div>
                <strong>Charles Deo</strong>
                <p>@Charles_deo</p>
              </div>
              <button type="button" className={styles.moreBtn}><Ellipsis size={18} /></button>
            </article>

            <article className={styles.friendsCard}>
              <h3>Friends</h3>
              <ul>
                {FRIENDS.map((friend) => (
                  <li key={friend.email}>
                    <div className={styles.friendAvatar} aria-hidden="true">👤</div>
                    <div>
                      <strong>{friend.name}</strong>
                      <p>{friend.email}</p>
                    </div>
                  </li>
                ))}
              </ul>
            </article>
          </aside>
        </section>
      </main>
    </div>
  );
}
